mapper.sql:
WHERE geom && ST_MakeEnvelope(#{bbox.minLng}, #{bbox.minLat}, #{bbox.maxLng}, #{bbox.maxLat}, 4326)


        AND deal_type IN
        #{dt}


        AND property_type IN
        #{pt}

    AND (CASE WHEN deal_type = 'WOLSE' THEN monthly_rent ELSE COALESCE(deal_amount, deposit) END) >= #{filter.priceMin}
    AND (CASE WHEN deal_type = 'WOLSE' THEN monthly_rent ELSE COALESCE(deal_amount, deposit) END) <= #{filter.priceMax}

mapper.select:
SELECT LEFT(res.lawd_cd, 5) AS region_cd, rs.region_name, rs.center_lat AS lat, rs.center_lon AS lng, COUNT(*) AS property_count, rs.avg_amount, rs.max_amount FROM real_estate_sales res JOIN region_summary rs ON rs.region_cd = LEFT(res.lawd_cd, 5) WHERE res.geom && ST_MakeEnvelope(#{bbox.minLng}, #{bbox.minLat}, #{bbox.maxLng}, #{bbox.maxLat}, 4326)
AND res.deal_type IN #{dt}
AND res.property_type IN #{pt}
AND (CASE WHEN res.deal_type = 'WOLSE' THEN res.monthly_rent ELSE COALESCE(res.deal_amount, res.deposit) END) >= #{filter.priceMin} AND (CASE WHEN res.deal_type = 'WOLSE' THEN res.monthly_rent ELSE COALESCE(res.deal_amount, res.deposit) END) <= #{filter.priceMax}
GROUP BY LEFT(res.lawd_cd, 5), rs.region_name, rs.center_lat, rs.center_lon, rs.avg_amount, rs.max_amount ORDER BY region_cd
